create table if not exists public.push_subscriptions (endpoint_id text primary key,endpoint text not null,p256dh text not null,auth text not null,user_agent text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());alter table public.push_subscriptions enable row level security;drop policy if exists "public can register a push subscription" on public.push_subscriptions;create policy "public can register a push subscription" on public.push_subscriptions for insert to anon,authenticated with check (endpoint_id is not null and endpoint is not null and p256dh is not null and auth is not null);drop policy if exists "public can update a matching push subscription" on public.push_subscriptions;create policy "public can update a matching push subscription" on public.push_subscriptions for update to anon,authenticated using (true) with check (endpoint_id is not null and endpoint is not null and p256dh is not null and auth is not null);
